param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop';function E($a,$b,$n){if($a-ne$b){throw "$n expected=$b actual=$a"}};function I($m,$p,$b=$null,$h=$null){$x=@{Method=$m;Uri="$BaseUrl$p";SkipHttpErrorCheck=$true};if($h){$x.Headers=$h};if($null-ne$b){$x.ContentType='application/json';$x.Body=$b|ConvertTo-Json -Compress};$r=Invoke-WebRequest @x;[pscustomobject]@{s=[int]$r.StatusCode;j=$r.Content|ConvertFrom-Json}};function U($p){$r=I POST '/api/auth/register' @{username="$p`_$(Get-Random -Minimum 100000 -Maximum 999999)";password='AddressEdge_2026'};@{h=@{Authorization="Bearer $($r.j.data.token)"}}}
$a=U 'addr_a';$b=U 'addr_b';$body=@{receiverName='A';phone='13800138000';province='上海市';city='上海市';district='浦东新区';detail='一号';defaultAddress=$true};$x=I POST '/api/addresses' $body $a.h;$body.detail='二号';$body.defaultAddress=$false;$y=I POST '/api/addresses' $body $a.h;$body.defaultAddress=$true;$up=I PUT "/api/addresses/$($y.j.data.id)" $body $a.h;E $up.s 200 'CART-006';$list=I GET '/api/addresses' $null $a.h;E @($list.j.data|Where-Object{$_.defaultAddress}).Count 1 'CART-003';$foreign=I DELETE "/api/addresses/$($y.j.data.id)" $null $b.h;E $foreign.s 404 'CART-008';$del=I DELETE "/api/addresses/$($x.j.data.id)" $null $a.h;E $del.s 200 'CART-007';$c=I POST '/api/cart-items' @{productId=3;quantity=1} $a.h;$f=I DELETE "/api/cart-items/$($c.j.data.id)" $null $b.h;E $f.s 404 'CART-028';Write-Host 'PASS: address/cart ownership edge.'
